<?php session_start();require_once "../config/database.php";function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,"UTF-8");}$error="";if($_SERVER["REQUEST_METHOD"]==="POST"){$u=trim($_POST["username"]??"");$p=$_POST["password"]??"";$s=$pdo->prepare("SELECT * FROM users WHERE username=? AND role='admin' LIMIT 1");$s->execute([$u]);$user=$s->fetch();if($user&&hash_equals((string)$user["password"],(string)$p)){$_SESSION["admin_id"]=$user["id"];$_SESSION["admin_name"]=$user["nama_lengkap"];$_SESSION["admin_username"]=$user["username"];header("Location: dashboard.php");exit;}$error="Username atau password salah.";}?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login Admin | Padi Seriti</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="admin.css"></head><body class="login-page"><div class="login-card"><div class="login-logo"><i class="fa-solid fa-wheat-awn"></i></div><div class="text-center mb-4"><h2>PADI SERITI</h2><p>Administrator Panel</p></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><div class="mb-3"><label>Username</label><div class="input-wrap"><i class="fa-solid fa-user"></i><input name="username" required></div></div><div class="mb-4"><label>Password</label><div class="input-wrap"><i class="fa-solid fa-lock"></i><input type="password" name="password" required></div></div><button class="login-submit">Masuk ke Dashboard</button></form></div></body></html>